package pt.realmvillagereconomy.test;

import net.minecraft.core.BlockPos;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.nbt.NbtAccounter;
import net.minecraft.nbt.NbtIo;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.item.trading.ItemCost;
import net.minecraft.world.item.trading.MerchantOffer;
import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;
import net.neoforged.neoforge.gametest.GameTestHolder;
import net.neoforged.neoforge.gametest.PrefixGameTestTemplate;
import pt.realmvillagereconomy.compat.ChroniclesBridge;
import pt.realmvillagereconomy.compat.CrownBridge;
import pt.realmvillagereconomy.data.EconomyData;
import pt.realmvillagereconomy.service.TradeItems;
import pt.realmvillagereconomy.service.TradingService;

@GameTestHolder("realmvillagereconomy") @PrefixGameTestTemplate(false)
public final class VillagerGameTests {
    private static boolean wallet(TradeFixture f){return ChroniclesBridge.loaded();}
    private static int count(TradeFixture f,net.minecraft.world.item.Item item){return f.player.getInventory().countItem(item);}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void purchaseBurnsOnlyTheBaseAndDeliversTheExactVanillaResult(GameTestHelper h){try(var f=new TradeFixture(h)){f.open(f.player);if(!wallet(f)){f.trade(f.player,0);h.assertTrue(count(f,Items.BREAD)==0,"Unbacked wallet purchase succeeded");}else{f.trade(f.player,0);h.assertTrue(ChroniclesBridge.balance(f.player)==90000&&count(f,Items.BREAD)==3&&f.merchant.getOffers().getFirst().getUses()==1&&f.merchant.getVillagerXp()==4,"Wallet/result/stock/xp not committed together");}}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void materialSalesStillPayPhysicalEmeraldsAndNeverDebitTheWallet(GameTestHelper h){try(var f=new TradeFixture(h)){f.offer(new MerchantOffer(new ItemCost(Items.WHEAT,20),new ItemStack(Items.EMERALD),12,2,.05F));f.player.getInventory().setItem(0,new ItemStack(Items.WHEAT,40));f.open(f.player);long balance=wallet(f)?ChroniclesBridge.balance(f.player):-1;f.trade(f.player,1);h.assertTrue(count(f,Items.WHEAT)==20&&count(f,Items.EMERALD)==1,"A material sale did not preserve physical emeralds");if(wallet(f))h.assertTrue(ChroniclesBridge.balance(f.player)==balance,"Selling taxed or converted the wallet");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void replayingTheSameNativeRequestCannotChargeOrDeliverTwice(GameTestHelper h){try(var f=new TradeFixture(h)){f.open(f.player);if(wallet(f)){var p=f.payload(f.player);p.addProperty("offer",0);TradingService.action(f.player,"trade",p.toString());TradingService.action(f.player,"trade",p.toString());h.assertTrue(count(f,Items.BREAD)==3&&ChroniclesBridge.balance(f.player)==90000&&f.merchant.getOffers().getFirst().getUses()==1,"Replayed request duplicated a trade");}}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void fullInventoryRejectsBeforeAnyWalletDebitOrOfferUse(GameTestHelper h){try(var f=new TradeFixture(h)){for(int i=0;i<36;i++)f.player.getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));f.open(f.player);f.trade(f.player,0);h.assertTrue(f.merchant.getOffers().getFirst().getUses()==0&&count(f,Items.BREAD)==0,"Full inventory consumed stock");if(wallet(f))h.assertTrue(ChroniclesBridge.balance(f.player)==100000,"Full inventory charged money");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void bookPurchasesKeepTheExtraVanillaMaterialRequirement(GameTestHelper h){try(var f=new TradeFixture(h)){f.offer(new MerchantOffer(new ItemCost(Items.EMERALD,2),java.util.Optional.of(new ItemCost(Items.BOOK)),new ItemStack(Items.ENCHANTED_BOOK),8,4,.05F));f.open(f.player);f.trade(f.player,1);h.assertTrue(count(f,Items.ENCHANTED_BOOK)==0&&f.merchant.getOffers().get(1).getUses()==0,"Missing physical book was ignored");if(wallet(f)){f.player.getInventory().setItem(0,new ItemStack(Items.BOOK));f.trade(f.player,1);h.assertTrue(count(f,Items.BOOK)==0&&count(f,Items.ENCHANTED_BOOK)==1&&ChroniclesBridge.balance(f.player)==99000,"Book input or exact converted price was wrong");}}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void customComponentsSurviveTheDurableInventoryTransaction(GameTestHelper h){try(var f=new TradeFixture(h)){var result=new ItemStack(Items.DIAMOND_SWORD);result.set(DataComponents.CUSTOM_NAME,Component.literal("The Crown's Blade"));f.offer(new MerchantOffer(new ItemCost(Items.EMERALD),result,4,4,.05F));f.open(f.player);if(wallet(f)){f.trade(f.player,1);h.assertTrue(ItemStack.isSameItemSameComponents(result,f.player.getInventory().getItem(0)),"Trade stripped custom item components");}}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void insufficientFundsCannotConsumeInventoryOrStock(GameTestHelper h){try(var f=new TradeFixture(h)){f.merchant.getOffers().clear();f.offer(new MerchantOffer(new ItemCost(Items.EMERALD,64),new ItemStack(Items.DIAMOND),8,4,.05F));if(wallet(f))TradeActors.profile(f.player,true,1);f.open(f.player);f.trade(f.player,0);h.assertTrue(count(f,Items.DIAMOND)==0&&f.merchant.getOffers().getFirst().getUses()==0,"Insufficient funds still delivered an item");if(wallet(f))h.assertTrue(ChroniclesBridge.balance(f.player)==1,"Insufficient funds debited the wallet");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void heroDiscountUsesTheActualVanillaAdjustedEmeraldCost(GameTestHelper h){try(var f=new TradeFixture(h)){f.player.addEffect(new MobEffectInstance(MobEffects.HERO_OF_THE_VILLAGE,1000,0));f.open(f.player);int discounted=f.merchant.getOffers().getFirst().getCostA().getCount();h.assertTrue(discounted<20&&f.view(f.player).getAsJsonArray("offers").get(0).getAsJsonObject().get("base").getAsLong()==discounted*500L,"Hero discount was lost during conversion");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void demandUsesTheVanillaPriceInsteadOfTheUndiscountedBaseCost(GameTestHelper h){try(var f=new TradeFixture(h)){var offer=f.merchant.getOffers().getFirst();for(int i=0;i<8;i++)offer.increaseUses();offer.updateDemand();f.open(f.player);h.assertTrue(f.view(f.player).getAsJsonArray("offers").get(0).getAsJsonObject().get("base").getAsLong()==offer.getCostA().getCount()*500L&&offer.getCostA().getCount()>20,"Demand price was not converted");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void changedOfferRequiresANewExplicitConfirmation(GameTestHelper h){try(var f=new TradeFixture(h)){f.open(f.player);var p=f.payload(f.player);p.addProperty("offer",0);f.merchant.getOffers().getFirst().increaseUses();TradingService.action(f.player,"trade",p.toString());h.assertTrue(count(f,Items.BREAD)==0&&f.merchant.getOffers().getFirst().getUses()==1,"A stale quote was accepted");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void anOrdinaryPlayerCannotApproveTaxes(GameTestHelper h){try(var f=new TradeFixture(h)){f.open(f.player);f.policy(f.player,1000);h.assertTrue(f.data.rate()==0,"An ordinary player changed the tax");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void anEmergencyAdministratorStillRespectsTheConfiguredCeiling(GameTestHelper h){try(var f=new TradeFixture(h)){f.op(f.player);f.open(f.player);f.policy(f.player,2501);h.assertTrue(f.data.rate()==0,"Administrator exceeded the configured ceiling through the UI");f.policy(f.player,1000);h.assertTrue(f.data.rate()==1000&&f.data.history().size()==1,"Emergency fiscal approval was not audited");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void theSwornPresidentLosesTaxPowersAsSoonAsTheMandateEnds(GameTestHelper h){if(!CouncilFixture.loaded()){h.succeed();return;}try(var council=new CouncilFixture(h.getLevel().getServer());var f=new TradeFixture(h)){long now=System.currentTimeMillis();council.mandate(f.player.getUUID(),now-1000,now+60000,0);f.open(f.player);f.policy(f.player,500);h.assertTrue(f.data.rate()==0,"Unsworn winner changed tax");council.claim(now-1);f.policy(f.player,1000);h.assertTrue(f.data.rate()==1000,"Sworn president could not approve tax");council.expire(now-1);f.policy(f.player,1500);h.assertTrue(f.data.rate()==1000,"Expired president changed the last approved tax");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void aSecondPlayerCannotStealThePhysicalMerchantSession(GameTestHelper h){try(var f=new TradeFixture(h)){f.open(f.player);boolean refused=false;try{f.open(f.other);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused&&f.merchant.getTradingPlayer()==f.player,"Second player stole the merchant");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void offHandInteractionCannotOpenABypassingVanillaMerchantMenu(GameTestHelper h){try(var f=new TradeFixture(h)){f.player.setPos(f.merchant.getX()+1,f.merchant.getY(),f.merchant.getZ());var event=new PlayerInteractEvent.EntityInteract(f.player,InteractionHand.OFF_HAND,f.merchant);TradingService.interact(event);h.assertTrue(event.isCanceled()&&f.player.containerMenu instanceof pt.realmvillagereconomy.menu.EconomyMenu,"Off-hand packet bypasses virtual prices");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void restoringAnOldVillagerChunkCannotResetTheConsumedOffer(GameTestHelper h)throws Exception{try(var f=new TradeFixture(h)){f.open(f.player);if(wallet(f)){f.trade(f.player,0);f.player.closeContainer();f.merchant.getOffers().getFirst().resetUses();f.merchant.setVillagerXp(0);f.merchant.getPersistentData().remove("realm_villager_revision");TradingService.restore(f.merchant);h.assertTrue(f.merchant.getOffers().getFirst().getUses()==1&&f.merchant.getVillagerXp()==4,"Stale world entity rolled back a durable purchase");}}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void aCurrentMerchantRevisionPreservesLaterVanillaRestocking(GameTestHelper h){try(var f=new TradeFixture(h)){f.open(f.player);if(wallet(f)){f.trade(f.player,0);f.merchant.getOffers().getFirst().resetUses();TradingService.restore(f.merchant);h.assertTrue(f.merchant.getOffers().getFirst().getUses()==0,"Recovery overwrote a newer Vanilla restock");}}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void treasuryAbsenceDisablesOnlyTheTaxAndRetainsTheApprovedRate(GameTestHelper h){if(CrownBridge.installed()){h.succeed();return;}try(var f=new TradeFixture(h)){f.data.policy(f.player.getUUID(),"QA",2000,false);f.open(f.player);h.assertTrue(f.view(f.player).get("rate").getAsInt()==0&&f.view(f.player).get("approvedRate").getAsInt()==2000,"Missing treasury destroyed or charged the approved tax");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void noNativeInventorySlotsExistToTradeWithPhysicalEmeralds(GameTestHelper h){try(var f=new TradeFixture(h)){f.open(f.player);h.assertTrue(f.player.containerMenu.slots.isEmpty(),"Native emerald/result slots bypass the receipted transaction");}h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void saleAndStockHaveAnActualCompressedFileReceipt(GameTestHelper h)throws Exception{try(var f=new TradeFixture(h)){f.offer(new MerchantOffer(new ItemCost(Items.WHEAT,2),new ItemStack(Items.EMERALD),8,1,.05F));f.player.getInventory().setItem(0,new ItemStack(Items.WHEAT,4));f.open(f.player);f.trade(f.player,1);var saved=NbtIo.readCompressed(f.data.path(),NbtAccounter.unlimitedHeap());EconomyData.validate(saved);h.assertTrue(!saved.contains("journal")&&saved.getCompound("merchants").contains(f.merchant.getUUID().toString()),"Sale has no durable stock overlay");}System.out.println("VILLAGER_NATIVE_PASSED");h.succeed();}
    @GameTest(template="trade_empty",timeoutTicks=100) public static void persistedReceiptInspectionNeverRebindsTheLiveAdvancementTracker(GameTestHelper h)throws Exception{
        try(var f=new TradeFixture(h)){if(wallet(f)){
            f.offer(new MerchantOffer(new ItemCost(Items.WHEAT,2),new ItemStack(Items.EMERALD),8,1,.05F));f.player.getInventory().setItem(0,new ItemStack(Items.WHEAT,4));f.open(f.player);
            var tracker=f.player.getAdvancements();var playerField=net.minecraft.server.PlayerAdvancements.class.getDeclaredField("player");playerField.setAccessible(true);Object owner=playerField.get(tracker);
            f.trade(f.player,0);h.assertTrue(playerField.get(tracker)==owner,"Receipt inspection rebound live advancements to a temporary player");f.trade(f.player,1);
            h.assertTrue(count(f,Items.EMERALD)==1&&ChroniclesBridge.balance(f.player)==90000&&f.data.journal()==null,"A purchase followed by a material sale failed");
        }}h.succeed();
    }
}
